const base64 = $input.first().json.stdout;  // pega a saída em base64

return {
  json: {
    arquivo: 'reporte-pagos.xls'
  },      // retorna um nove para o arquivo e os dados abaixo
  binary: {
    data: {
      data: base64.trim(),    //conteudo em base64
      mimeType: 'application/vnd.ms-excel',  //indica que é xls
      fileName: 'reporte-pagos.xls'   
    }
  }
};

return $input.all().filter(item => {
  const referencia = String(item.json["Referência"] ?? "").trim(); 
  //pega somente o campo referencia do JSON

  return referencia.startsWith("2"); // Só NF
});

return $input.all().map(item => {
  const referencia = String(item.json["Referência"] ?? "").trim();

  const nf = referencia   // Separa o numero da nf, tirando 0
    .split("-")[0]
    .replace(/^0+/, "");

  return {
    json: {
      ...item.json,
      NF: nf   // retorna o numero formatado 
    }
  };
});

// Pega aquele JSON gigante do nó anterior
const googleData = $input.first().json;

// Extrai apenas o Nome e o ID interno de cada aba (precisaremos do ID para pintar de ciano depois)
const abas = googleData.sheets.map(aba => ({
  nome: aba.properties.title,
  id: aba.properties.sheetId
}));

// Resgata todas as NFs limpas que ficaram paradas lá no nó 'LIMPAR NF'
const notasParaProcurar = $('LIMPAR NF').all().map(item => item.json.NF);

return {
  json: {
    resumo: `Vamos procurar ${notasParaProcurar.length} notas em ${abas.length} abas.`,
    listaAbas: abas,
    notas: notasParaProcurar
  }
};

const dados = $input.first().json;

// Prepara a lista de busca no formato JSON que o Google exige
const dataFilters = dados.listaAbas.map(aba => ({
  a1Range: `'${aba.nome}'!J:J`
}));

return {
  json: {
    listaAbas: dados.listaAbas,
    notas: dados.notas,
    bodyBusca: {
      dataFilters: dataFilters
    }
  }
};

// Pega a resposta com as colunas J que acabaram de chegar
const googleResponse = $input.first().json;

// AQUI: Coloque o nome exato do seu nó Code que gerou a listaAbas.
// Pela sua imagem anterior, deve ser 'Code in JavaScript1'. Se for outro, mude abaixo.
const dadosPreparados = $('Code in JavaScript1').first().json; 
const notasParaProcurar = dadosPreparados.notas;
const listaAbas = dadosPreparados.listaAbas;

const notasEncontradas = [];
const formatRequests = [];

// Vamos caçar cada uma das notas
for (const nota of notasParaProcurar) {
  for (const abaData of googleResponse.valueRanges) {
    if (!abaData.valueRange || !abaData.valueRange.values) continue;

    const colValues = abaData.valueRange.values;
    // Tira as aspas simples do nome da aba (ex: "'KIKO - 24TL'" vira "KIKO - 24TL")
    const nomeAbaBruto = abaData.valueRange.range.split('!')[0].replace(/'/g, '');

    // Procura em qual linha está
    const rowIndex = colValues.findIndex(row => {
      if (row && row.length > 0) {
        // Limpa o valor da célula da mesma forma que fizemos com a nota
        // Pega o valor, separa no "-" e tira os zeros iniciais
        const valorCelula = String(row[0]).split('-')[0].replace(/^0+/, '').trim();
        return valorCelula === String(nota).trim();
      }
      return false;
    });

    if (rowIndex !== -1) {
      // Achou a nota! Vamos pegar o ID da aba
      const sheetIdObj = listaAbas.find(a => a.nome === nomeAbaBruto);

      if (sheetIdObj) {
        notasEncontradas.push({
          nota: nota,
          aba: nomeAbaBruto,
          linhaExcel: rowIndex + 1
        });

        // Cria a ordem para o Google pintar a célula de Ciano
        // Ciano = Red: 0, Green: 1, Blue: 1
        // Coluna J no Google equivale ao índice Numérico 9
        formatRequests.push({
          repeatCell: {
            range: {
              sheetId: sheetIdObj.id,
              startRowIndex: rowIndex,      // Index 0 = Linha 1
              endRowIndex: rowIndex + 1,    // Pinta só essa linha
              startColumnIndex: 9,          // Começa na Coluna J
              endColumnIndex: 10            // Termina na Coluna J
            },
            cell: {
              userEnteredFormat: {
                backgroundColor: { red: 0.0, green: 1.0, blue: 1.0 }
              }
            },
            fields: "userEnteredFormat.backgroundColor"
          }
        });
      }
      break; // Já achamos a nota, pode parar de procurar ela nas outras abas
    }
  }
}

return {
  json: {
    resumo: `De ${notasParaProcurar.length} notas buscadas, encontramos ${formatRequests.length} na planilha da MA2!`,
    notasEncontradas: notasEncontradas,
    bodyPintar: {
      requests: formatRequests
    }
  }
};

// Pega a lista de notas que foram pintadas de ciano com sucesso
const encontradas = $input.first().json.notasEncontradas.map(item => String(item.nota));

// Pega TODOS os dados originais, com data, valor e quantidade, lá do nó 'LIMPAR NF'
const todasAsNotasOriginais = $('LIMPAR NF').all();

// O Filtro: mantemos apenas as notas originais que NÃO estão na lista das encontradas
const faltantes = todasAsNotasOriginais.filter(item => {
  const notaLimpa = String(item.json.NF);
  return !encontradas.includes(notaLimpa); // Se não incluiu, é faltante
});

// Se não tiver faltantes, ele retorna vazio (e o fluxo encerra feliz)
return faltantes;

// Pega o arquivo binário do disco (buffer) na propriedade 'data' do item 0
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

// Converte o conteúdo real do arquivo para texto Base64
const base64Text = buffer.toString('base64');

return {
  json: {
    arquivoBase64: base64Text
  }
};
